/**
 * Countdown's states fixture in element form, with the React fixture's entry
 * names, so a contract's `when <state>` names the same entry in every shell. Each
 * entry is the markup a page writes, and what its script sets once the elements
 * are defined.
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/countdown.ts`. Never edit it by hand.
 */
import { holding, listen, type ComponentStates } from '@polymorph/elements'

import '../controls/Button'
import '../layout/Inline'
import './Countdown'
import './Text'

export const states: ComponentStates = {
  component: 'Countdown',
  entries: [
    {
      name: 'minutes — m:ss',
      html: `<poly-countdown label="Time until the code expires"></poly-countdown>`,
      subject: 'poly-countdown',
      setup: (find) => {
        const e0 = find('poly-countdown', 0)
        e0.until = new Date(Date.now() + 299_000).toISOString()
      },
      expect: { 'data-ended': null },
    },
    {
      name: 'hours — h:mm:ss from an hour',
      html: `<poly-countdown label="Time until the session ends"></poly-countdown>`,
      subject: 'poly-countdown',
      setup: (find) => {
        const e0 = find('poly-countdown', 0)
        e0.until = new Date(Date.now() + 3_725_000).toISOString()
      },
    },
    {
      name: 'ended — 0:00 once the moment is reached',
      html: `<poly-countdown label="Time until the code expires"></poly-countdown>`,
      subject: 'poly-countdown',
      setup: (find) => {
        const e0 = find('poly-countdown', 0)
        e0.until = new Date(Date.now() - 5_000).toISOString()
      },
      expect: { 'data-ended': '' },
    },
    {
      name: 'locale — the locale’s numerals and words',
      html: `<poly-countdown label="Time until the code expires" locale="ar-EG"></poly-countdown>`,
      subject: 'poly-countdown',
      setup: (find) => {
        const e0 = find('poly-countdown', 0)
        e0.until = new Date(Date.now() + 299_000).toISOString()
      },
    },
    {
      name: 'announced — a polite line at one minute and at ten seconds',
      html: `<poly-countdown label="Time until the code expires" announce></poly-countdown>`,
      subject: 'poly-countdown',
      setup: (find) => {
        const e0 = find('poly-countdown', 0)
        e0.until = new Date(Date.now() + 65_000).toISOString()
      },
    },
    {
      name: 'beside a Button — the application enables it at the end',
      html: `<poly-inline gap="3" align="center">
  <poly-text>Send a new code in <poly-countdown label="Time until a new code can be sent"></poly-countdown></poly-text>
  <poly-button variant="outline" tone="neutral" size="sm" label="Send a new code"></poly-button>
</poly-inline>`,
      subject: 'poly-countdown',
      setup: (find) => {
        const held = holding({ locked: true, until: new Date(Date.now() + 30_000).toISOString() })
        const e0 = find('poly-countdown', 0)
        held.bind('until', e0, 'until')
        listen(e0, 'poly-end', () => held.set('locked', false))
        const e1 = find('poly-button', 0)
        held.bind('locked', e1, 'disabled')
      },
    },
    {
      name: 'invalid — no moment, so nothing renders',
      html: `<poly-countdown until="not-a-moment" label="Time until the code expires"></poly-countdown>`,
      subject: 'poly-countdown',
      rendersNothing: true,
    },
  ],
}
